    len = strlen(param->key) + strlen(param->string) + 2;
    if (len > ctx->data_size - size)
        return invalf(fc, "VFS: Legacy: ...");
    ...
    memcpy(ctx->legacy_data + size, param->key, strlen(param->key));
    ...
}
```

